func refMatch(patterns []string, path string) string {
	best := ""
	var try func(pat []string, seg []string) bool
	// returns true if match found; sets best (first found by priority)
	// simple recursive with priority ordering
	var match func(pat, seg []string) bool
	match = func(pat, seg []string) bool {
		if len(pat) == 0 {
			return len(seg) == 0
		}
		if pat[0] == "*" {
			return true // matches rest (including empty)
		}
		if len(seg) == 0 {
			return false
		}
		if strings.HasPrefix(pat[0], ":") {
			return match(pat[1:], seg[1:])
		}
		if pat[0] == seg[0] {
			return match(pat[1:], seg[1:])
		}
		return false
	}
	_ = try
	// order patterns: static-first by comparing segment kinds lexicographically (static<param<any)
	type cand struct {
		p    string
		kind []int
	}
	var cands []cand
	for _, p := range patterns {
		segs := strings.Split(p, "/")
		var kinds []int
		for _, s := range segs {
			switch {
			case s == "*":
				kinds = append(kinds, 2)
			case strings.HasPrefix(s, ":"):
				kinds = append(kinds, 1)
			default:
				kinds = append(kinds, 0)
			}
		}
		cands = append(cands, cand{p, kinds})
	}
	sort.SliceStable(cands, func(i, j int) bool {
		a, b := cands[i].kind, cands[j].kind
		for k := 0; k < len(a) && k < len(b); k++ {
			if a[k] != b[k] {
				return a[k] < b[k]
			}
