package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

var routePool = []string{
	"/", "/a", "/a/b", "/a/b/c", "/:p", "/:p/b", "/a/:p", "/a/:p/c", "/a/*", "/*", "/:p/*", "/:p/:q", "/a/:p/:q", "/ab", "/abc", "/a/c", "/a/b/:p", "/:p/:q/*", "/x/:p", "/x/y", "/a/:p/:q/:r",
}

var segs = []string{"a", "b", "c", "x", "y", "ab", "abc"}

func randPath(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	s := ""
	for i := 0; i < n; i++ {
		s += "/" + segs[rnd.Intn(len(segs))]
	}
	return s
}

// does pattern match path (echo semantics: :p matches exactly one segment, * matches rest)
func refMatch(pat, path string) bool {
	ps := strings.Split(pat, "/")
	hs := strings.Split(path, "/")
	for i := 0; i < len(ps); i++ {
		if ps[i] == "*" {
			return true
		}
		if i >= len(hs) {
			return false
		}
		if strings.HasPrefix(ps[i], ":") {
			continue
		}
		if ps[i] != hs[i] {
			return false
		}
	}
	return len(ps) == len(hs)
}

func TestBruteFalsePositive(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	fp := 0
	for iter := 0; iter < 200000; iter++ {
		nr := 1 + rnd.Intn(4)
		routes := make([]string, 0, nr)
		for i := 0; i < nr; i++ {
			routes = append(routes, routePool[rnd.Intn(len(routePool))])
		}
		e := New()
		r := e.router
		for _, p := range routes {
			r.Add(http.MethodGet, p, func(c Context) error { return nil })
		}
		path := randPath(rnd)
		c := e.NewContext(nil, nil).(*context)
		r.Find(http.MethodGet, path, c)
		if c.path != path {
			if !refMatch(c.path, path) {
