+// bindDataToMap binds data to a map destination. Supported map types are
+// map[string]string (binds first value from data slice), map[string][]string and
+// map[string]interface{} (bind the whole data slice).
+func (b *DefaultBinder) bindDataToMap(destination interface{}, data map[string][]string, _ string) error {
+	if destination == nil || len(data) == 0 {
+		return nil
+	}
+	typ := reflect.TypeOf(destination).Elem()
+	val := reflect.ValueOf(destination).Elem()
+
+	if typ.Kind() != reflect.Map {
+		return errors.New("binding element must be a map")
+	}
+	if typ.Key().Kind() != reflect.String {
+		return errors.New("binding element must be a map[string]...")
+	}
+
+	elemKind := typ.Elem().Kind()
+	switch {
+	case elemKind == reflect.String:
+		for k, v := range data {
+			if len(v) == 0 {
+				continue
+			}
+			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
+		}
+	case elemKind == reflect.Slice && typ.Elem().Elem().Kind() == reflect.String:
+		for k, v := range data {
+			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
+		}
+	case elemKind == reflect.Interface:
+		for k, v := range data {
+			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
+		}
+	default:
+		// unsupported map type - do not bind anything
+		return nil
+	}
+	return nil
